import local.codex.ledger.*;import java.nio.file.*;import java.util.*;
public class TestMiRoundtrip {public static void main(String[] args)throws Exception{
 StatementImporter.Result original=StatementImporter.parse(Files.readAllBytes(Paths.get(args[0])),args[0]);byte[] bytes=MiExport.write(original.entries);StatementImporter.Result round=StatementImporter.parse(bytes,"roundtrip.xlsx");if(original.entries.size()!=round.entries.size())throw new AssertionError("Row count");for(int i=0;i<original.entries.size();i++){StatementImporter.Entry a=original.entries.get(i),b=round.entries.get(i);if(!StatementImporter.miKey(a).equals(StatementImporter.miKey(b))||!a.id.equals(b.id))throw new AssertionError("Data/ID lost on row "+i);}Files.createDirectories(Paths.get("work"));Files.write(Paths.get("work/mi-roundtrip.xlsx"),bytes);System.out.println("PASS Xiaomi XLSX six-field roundtrip and stable IDs");}}
